mapper.select:
select count(*)
from sd_download_log
where created_at >= #{fromTime}
    and created_at < #{toTime}
    and upper(coalesce(download_status, 'SUCCESS')) = 'SUCCESS'

select download_count
from sd_dataset_stat
where dataset_id = #{datasetId}

select view_count
from sd_dataset_stat
where dataset_id = #{datasetId}

select count(*)
from sd_dataset_favorite
where dataset_id = #{datasetId}
    and user_id = #{userId}

mapper.delete:
delete from sd_dataset_favorite
where dataset_id = #{datasetId}
    and user_id = #{userId}

mapper.update:
update sd_dataset_stat 
set view_count = view_count + 1, updated_at = now()
where dataset_id = #{datasetId}

update sd_dataset_stat 
set download_count = download_count + 1, updated_at = now()
where dataset_id = #{datasetId}

mapper.select:
select count(*)
from sd_dataset_view_log
where dataset_id = #{datasetId}
and user_id = #{userId}
and created_at >= #{fromTime}

select count(*)
from sd_dataset_view_log
where dataset_id = #{datasetId}
and user_id is null
and view_ip = #{viewIp}
and created_at >= #{fromTime}

select c.category_name_ko  from sd_gis_dataset d
inner join sd_data_category c on d.category_id  = c.category_id 
where dataset_id = #{datasetId};

select u.organization  from sd_gis_dataset d
inner join sd_user u on d.created_by  = u.user_id
where d.dataset_id = #{datasetId};
